async function obterUtilizador(id) {
  const resposta = await fetch(`/api/utilizadores/${id}`);
  if (!resposta.ok) {
    throw new Error(`Pedido falhou com estado ${resposta.status}`);
  }
  return resposta.json();
}

// Promise nunca é tratada: nem .catch(), nem está dentro de um try/catch
obterUtilizador(999);

// No browser, este erro só é reportado através do evento global:
window.addEventListener('unhandledrejection', (evento) => {
  console.error('Rejeição não tratada:', evento.reason);
  evento.preventDefault(); // evita o aviso por omissão do browser, mas não resolve o problema
});

// No Node.js o equivalente é:
process.on('unhandledRejection', (razao, promessa) => {
  console.error('Rejeição não tratada:', razao);
});

async function obterPedidos(idUtilizador) {
  const resposta = await fetch(`/api/utilizadores/${idUtilizador}/pedidos`);
  if (!resposta.ok) {
    throw new Error(`Pedido falhou com estado ${resposta.status}`);
  }
  return resposta.json();
}

function processarPedidos(pedidos) {
  return pedidos.map(pedido => pedido.total);
}

// Com .catch() numa cadeia
function comCatchNaCadeia() {
  return obterUtilizador(1)
    .then(utilizador => obterPedidos(utilizador.id))
    .then(pedidos => processarPedidos(pedidos))
    .catch(erro => {
      console.error('Falha ao processar utilizador:', erro.message);
      return [];
    });
}

// Com try/catch à volta de await
async function comTryCatch() {
  try {
    const utilizador = await obterUtilizador(1);
    const pedidos = await obterPedidos(utilizador.id);
    return processarPedidos(pedidos);
  } catch (erro) {
    console.error('Falha ao processar utilizador:', erro.message);
    return [];
  }
}

// Bug comum: falta o await antes do return
async function comBug() {
  try {
    return obterUtilizador(1); // devia ser: return await obterUtilizador(1)
  } catch (erro) {
    // nunca chega a executar se a promise só rejeitar depois de o try terminar
    console.error(erro);
  }
}

class ErroDeValidacao extends Error {
  constructor(mensagem, campo) {
    super(mensagem);
    this.name = 'ErroDeValidacao';
    this.campo = campo;
  }
}

function validarEmail(email) {
  if (typeof email !== 'string' || !email.includes('@')) {
    throw new ErroDeValidacao('Email inválido', 'email');
  }
}

async function registarUtilizador(dados) {
  validarEmail(dados.email); // lança de forma síncrona, antes de qualquer pedido de rede

  if (!dados.password || dados.password.length < 8) {
    throw new ErroDeValidacao('A password deve ter pelo menos 8 caracteres', 'password');
  }

  const resposta = await fetch('/api/utilizadores', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(dados),
  });

  if (!resposta.ok) {
    throw new Error(`Erro do servidor: ${resposta.status}`);
  }

  return resposta.json();
}

(async () => {
  try {
    await registarUtilizador({ email: 'ana@exemplo.com', password: '123' });
  } catch (erro) {
    if (erro instanceof ErroDeValidacao) {
      console.warn(`Campo inválido (${erro.campo}): ${erro.message}`);
    } else {
      console.error('Erro inesperado:', erro);
    }
  }
})();

function esperar(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function comRetry(funcaoAssincrona, tentativasMaximas = 3, atrasoBase = 300) {
  for (let tentativa = 1; tentativa <= tentativasMaximas; tentativa++) {
    try {
      return await funcaoAssincrona();
    } catch (erro) {
      const ultimaTentativa = tentativa === tentativasMaximas;

      // Erros de validação não devem ser repetidos: vão falhar sempre da mesma forma
      if (erro instanceof ErroDeValidacao || ultimaTentativa) {
        throw erro;
      }

      const atraso = atrasoBase * 2 ** (tentativa - 1); // 300ms, 600ms, 1200ms, ...
      console.warn(`Tentativa ${tentativa} falhou (${erro.message}). A repetir em ${atraso}ms...`);
      await esperar(atraso);
    }
  }
}

// Utilização:
const dados = await comRetry(() =>
  fetch('/api/relatorio').then(resposta => {
    if (!resposta.ok) throw new Error(`Estado ${resposta.status}`);
    return resposta.json();
  })
);

class ErroOperacional extends Error {
  constructor(mensagem) {
    super(mensagem);
    this.name = 'ErroOperacional';
    this.operacional = true; // erro esperado: problema de negócio ou de rede
  }
}

class ErroDeRecursoNaoEncontrado extends ErroOperacional {
  constructor(recurso) {
    super(`${recurso} não encontrado`);
    this.name = 'ErroDeRecursoNaoEncontrado';
  }
}

async function obterPedido(id) {
  const pedidos = { 1: { itens: [{ preco: 10 }, { preco: 20 }] } };
  return pedidos[id];
}

async function processarPedido(id) {
  const pedido = await obterPedido(id);

  if (!pedido) {
    throw new ErroDeRecursoNaoEncontrado(`Pedido ${id}`);
  }

  // Se "pedido.itens" não existisse por um erro de lógica algures,
  // isto lançaria um TypeError normal, não um erro operacional
  return pedido.itens.map(item => item.preco);
}

async function tratarPedido(id) {
  try {
    return await processarPedido(id);
  } catch (erro) {
    if (erro.operacional) {
      console.warn('Erro esperado:', erro.message);
      return null; // resposta controlada, por exemplo um 404 para o cliente
    }

    // Erro inesperado: regista com detalhe e propaga, nunca esconder um bug
    console.error('Bug inesperado:', erro);
    throw erro;
  }
}

