      } else {
        resolve(34);
      }
    }, 100);
  });
}

async function obterIdade(deveFalhar) {
  try {
    const idade = await simularPedido(deveFalhar);
    return idade;
  } catch (erro) {
    console.error(`Não foi possível obter a idade: ${erro.message}`);
