class ErroDeValidacao extends Error {
  constructor(mensagem, campo) {
    super(mensagem);
    this.name = 'ErroDeValidacao';
    this.campo = campo;
  }
}

async function criarProduto(dados) {
  if (typeof dados.nome !== 'string' || dados.nome.trim() === '') {
    throw new ErroDeValidacao('O nome é obrigatório', 'nome');
  }

  if (typeof dados.preco !== 'number' || dados.preco <= 0) {
    throw new ErroDeValidacao('O preço deve ser um número maior que zero', 'preco');
  }

  const produtoGravado = await new Promise(resolve =>
    setTimeout(() => resolve({ ...dados, id: 1 }), 50)
  );

  return produtoGravado;
}

(async () => {
  try {
    const produto = await criarProduto({ nome: '', preco: 10 });
    console.log('Produto criado:', produto);
  } catch (erro) {
    if (erro instanceof ErroDeValidacao) {
      console.warn(`Campo inválido (${erro.campo}): ${erro.message}`);
    } else {
      console.error('Erro inesperado:', erro);
    }
  }
})();

exercises.statement:
Tem o seguinte código:

async function obterPedido(id) {
  const pedidos = { 1: { itens: [{ preco: 10 }, { preco: 20 }] } };
  return pedidos[id];
}

async function totalDoPedido(id) {
  const pedido = await obterPedido(id);
  return pedido.itens.reduce((soma, item) => soma + item.preco, 0);
}

Se chamar totalDoPedido(2) (um id inexistente), o código atual lança um TypeError confuso, porque pedido é undefined. Crie uma classe PedidoNaoEncontrado que estenda Error, receba o id no construtor, defina uma mensagem clara e marque a instância com uma propriedade esperado = true. Altere totalDoPedido para lançar um PedidoNaoEncontrado quando o pedido não existir, em vez de deixar o TypeError acontecer. Depois escreva uma função assíncrona chamarComTratamento(id) que chama totalDoPedido(id) dentro de um try/catch e: se o erro apanhado tiver esperado === true, escreve na consola "Pedido inválido: " seguido da mensagem do erro; caso contrário, escreve "Erro inesperado, a reportar à equipa:" seguido do erro, e relança esse erro.

exercises.solution_code:
class PedidoNaoEncontrado extends Error {
  constructor(id) {
    super(`Pedido com id ${id} não encontrado`);
    this.name = 'PedidoNaoEncontrado';
    this.esperado = true;
  }
}

async function obterPedido(id) {
  const pedidos = { 1: { itens: [{ preco: 10 }, { preco: 20 }] } };
  return pedidos[id];
}

async function totalDoPedido(id) {
  const pedido = await obterPedido(id);

  if (!pedido) {
    throw new PedidoNaoEncontrado(id);
  }

  return pedido.itens.reduce((soma, item) => soma + item.preco, 0);
}

async function chamarComTratamento(id) {
  try {
    const total = await totalDoPedido(id);
    console.log(`Total do pedido: ${total}`);
  } catch (erro) {
    if (erro.esperado) {
      console.warn(`Pedido inválido: ${erro.message}`);
    } else {
      console.error('Erro inesperado, a reportar à equipa:', erro);
      throw erro;
    }
  }
}

chamarComTratamento(2);

function esperar(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function comRetry(funcaoAssincrona, { tentativasMaximas = 4, atrasoBase = 200 } = {}) {
  for (let tentativa = 1; tentativa <= tentativasMaximas; tentativa++) {
    try {
      return await funcaoAssincrona();
    } catch (erro) {
      const ultimaTentativa = tentativa === tentativasMaximas;

      if (!erro.transitorio || ultimaTentativa) {
        throw erro;
      }

      const atraso = atrasoBase * 2 ** (tentativa - 1);
      console.warn(`Tentativa ${tentativa} falhou, a repetir em ${atraso}ms...`);
      await esperar(atraso);
    }
  }
}

let chamadas = 0;
function operacaoInstavel() {
  chamadas++;
  return new Promise((resolve, reject) => {
    if (chamadas <= 2) {
      const erro = new Error('Falha temporária');
      erro.transitorio = true;
      reject(erro);
    } else {
      resolve('sucesso');
    }
  });
}

(async () => {
  const resultado = await comRetry(operacaoInstavel);
  console.log('Resultado final:', resultado);
})();
